const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const required=Array.isArray(input.required_evidence)?input.required_evidence:[];
const verified=Array.isArray(input.verified_evidence)?input.verified_evidence:[];
const failed=Array.isArray(input.failed_evidence)?input.failed_evidence:[];
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const verifiedSet=new Set(verified.map(v=>String(typeof v==="string"?v:v.type||v.name||"").toLowerCase()).filter(Boolean));
const missing=required.filter(v=>!verifiedSet.has(String(typeof v==="string"?v:v.type||v.name||"").toLowerCase()));
const incomplete=milestones.filter(m=>!["completed","complete","done"].includes(String(m.status||"").toLowerCase()));
const criticalOverdue=milestones.filter(m=>m.critical===true&&(m.status==="overdue"||m.overdue===true));
let status="blocked",nextWorkflow="WF-126",reason="";
if(blockers.length){status="blocked";reason="active closing blockers remain";}
else if(failed.length){status="recovery_required";nextWorkflow="WF-307";reason="closing evidence has failed items requiring recovery";}
else if(criticalOverdue.length){status="recovery_required";nextWorkflow="WF-307";reason="critical milestone exception requires recovery routing";}
else if(missing.length){status="evidence_gap";nextWorkflow="WF-307";reason="required closing evidence is missing";}
else if(incomplete.length){status="incomplete";nextWorkflow="WF-305";reason="closing milestones remain incomplete";}
else{status="reconciled";nextWorkflow="WF-307";reason="required evidence and closing milestones reconcile successfully";}
const idempotencyKey=input.idempotency_key||`wf-306:${input.deal_id||"unknown"}:${input.evidence_version||input.version||1}`;
return [{json:{...input,workflow:"WF-306",workflow_name:"Milestone Exception → Closing Evidence/Reconciliation & Recovery Controller",status,closing_evidence:{required_count:required.length,verified_count:verified.length,missing,failed_count:failed.length,incomplete_milestone_count:incomplete.length,critical_overdue_count:criticalOverdue.length,blockers},next_workflow:nextWorkflow,human_review_required:status!=="reconciled",audit:{event_type:"closing_evidence_reconciliation",idempotency_key:idempotencyKey,reason}}}];
